import{Q as e,Z as t,ft as n,t as r}from"./chunks/framework.Dh28gFYL.js";var i=JSON.parse(`{"title":"Project Discipline","description":"","frontmatter":{},"headers":[],"relativePath":"deep-dive/discipline.md","filePath":"en/deep-dive/discipline.md","lastUpdated":1792296125000}`),a={name:`deep-dive/discipline.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="project-discipline" tabindex="-1">Project Discipline <a class="header-anchor" href="#project-discipline" aria-label="Permalink to “Project Discipline”">​</a></h1><h2 id="data-normalization" tabindex="-1">Data Normalization <a class="header-anchor" href="#data-normalization" aria-label="Permalink to “Data Normalization”">​</a></h2><p>Data normalization means the data from external sources are transformed into a canonical form used within Sync Engine.</p><ul><li>For &quot;unreliable&quot; entries (user input, or standard implemented by many servers), all data that are necessary to normalize must be normalized exactly and only once upon the point of entry. No further normalization should be executed within Sync Engine.</li><li>For &quot;reliable&quot; entries (proprietary APIs implemented by a single provider), there should not be normalization at all.</li></ul><p>Special data are separated into the following categories that should be always normalized regardless of source reliability:</p><ul><li>File size: single number of this size converted to bytes. For user-friendly display, convert them into number + space + capitalized unit, such as <code>1 GB</code>, <code>537 MB</code>, <code>29.9 KB</code> with base 1024 (so strictly the units are <code>KiB</code>/<code>MiB</code>/..., but use the units without <code>i</code> for understanding), max 2 decimal places.</li><li>Time duration: integer Unix timestamp specified to milliseconds. User-friendly display uses number + space + lower case unit, such as <code>1 s</code>, <code>24 h</code>, <code>2.3 d</code>, max 2 decimal places.</li><li>File path (key): follow <a href="./file-system#unified-key-schema">unified key</a> - <code>folder/file.ext</code>, folder - <code>folder/nested/</code>, root: <code>/</code>. Normalize to Unicode NFC.</li><li>URL: all URLs&#39; path name, query parameters, and fragment are percent-encoded according to RFC 3986; ASCII latin characters in protocol and hostname converted to lower case. For user-friendly display, decode the pathname, query parameters, and fragment.</li><li>ETag: strip the <code>W/</code> weak ETag marker and surrounding quotes.</li></ul><h2 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to “Documentation”">​</a></h2><ul><li>The primary documentation locates in <code>docs/src/pages/en/</code> has three sections in three folders: <code>usage/</code>, <code>development/</code>, and <code>deep-dive/</code>: <ul><li><code>usage/</code>: designed for non-technical users, avoid dev jargon</li><li><code>development/</code>: SDK API reference and practical module development setups only</li><li><code>deep-dive/</code>: Sync Engine internals</li></ul></li><li>Prefer inter-page links when other pages have relevant content, duplication content cross-page is forbidden.</li><li>Link format: Link to title anchors when possible, strict relative links, no <code>.md</code> extension.</li><li>Only add inter-links when the content is truly relevant, you must not link distant pages just for link count.</li><li>Link topology: <ul><li><code>usage/</code> and <code>deep-dive/</code> can interlink</li><li><code>development/</code> can link to <code>usage/</code> and <code>deep-dive/</code>, but <code>usage/</code> and <code>deep-dive/</code> should avoid linking into <code>development/</code>.</li><li>Module specs (<code>deep-dive/modules/*</code>) should be self-contained in each page in. They can link external pages but external pages should not link official modules except in dedicated pages in <code>usage/</code>.</li></ul></li><li>Don&#39;t be overly verbose.</li><li>Avoid large blocks of code in <code>usage/</code> and <code>deep-dive/</code>, code should be the major content in <code>development/</code></li><li>Documentation titles use title case.</li></ul>`,8)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};